-- 2) Lost update vs atomic update (READ COMMITTED)
-- BAD (application read-modify-write): two workers both read qty=10, both write 9
SELECT qty FROM inventory WHERE id = 1;          -- 10
UPDATE inventory SET qty = 9 WHERE id = 1;

-- GOOD: let the database do the arithmetic under the row lock
UPDATE inventory SET qty = qty - 1 WHERE id = 1 AND qty > 0;

-- Or lock explicitly when logic must run in between
BEGIN;
SELECT qty FROM inventory WHERE id = 1 FOR UPDATE;   -- others wait here
UPDATE inventory SET qty = 9 WHERE id = 1;
COMMIT;
```

