-- 3) Postgres as a job queue: many workers, no double-processing
BEGIN;
SELECT id, payload FROM jobs
WHERE status = 'PENDING'
ORDER BY created_at
LIMIT 10
FOR UPDATE SKIP LOCKED;        -- rows locked by other workers are skipped, not waited on
-- process them, then:
UPDATE jobs SET status = 'DONE' WHERE id = ANY(ARRAY[1,2,3]);
COMMIT;
