# 4) Retrying serialization failures and deadlocks (psycopg2)
import random, time
from psycopg2 import errors

RETRYABLE = (errors.SerializationFailure, errors.DeadlockDetected)

def run_in_tx(conn, fn, attempts=5):
    for i in range(attempts):
        try:
            with conn:                     # COMMIT on success, ROLLBACK on exception
                with conn.cursor() as cur:
                    return fn(cur)         # fn must be safe to re-run from scratch
        except RETRYABLE:
            if i == attempts - 1:
                raise
            time.sleep(min(2 ** i * 0.1, 2) + random.random() * 0.1)   # jittered backoff

# conn.set_session(isolation_level="SERIALIZABLE") for strict invariants
